// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.cloudimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport okhttp3.OkHttpClient/** * NOUS — Cloud Provider Factory. * * Creates [CloudLlmProvider] instances from [CloudProviderConfig]. * Supports all API protocols (OpenAI-compatible, Anthropic, Gemini). * * User can add ANY provider — no code change needed when new provider launches. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§6 CloudProviderFactory</a> */class CloudProviderFactory(    private val credentialVault: CredentialVaultInterface,) {    /**     * Create a CloudLlmProvider from config.     *     * All providers use the same [OkHttpCloudProvider] implementation —     * the API protocol differences are handled internally via [StreamParser].     */    fun create(config: CloudProviderConfig, httpClient: OkHttpClient): CloudLlmProvider {        return OkHttpCloudProvider(            config = config,            httpClient = httpClient,            credentialVault = credentialVault,        )    }    /**     * Create providers for all enabled configs.     */    fun createAll(        configs: List<CloudProviderConfig>,        httpClient: OkHttpClient,    ): List<CloudLlmProvider> {        return configs            .filter { it.isEnabled }            .map { create(it, httpClient) }    }}